#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>

/* Example: Block SIGINT for a short period */
int main(void) {
    sigset_t blocked_mask, old_mask;

    // 1. Initialize the set to contain SIGINT
    if (sigemptyset(&blocked_mask) == -1 || sigaddset(&blocked_mask, SIGINT) == -1) {
        perror("Failed to initialize signal set");
        return EXIT_FAILURE;
    }

    printf("Blocking SIGINT (Ctrl+C). Try sending the signal now...\n");

    // 2. Block the signal, saving the current mask in old_mask
    if (sigprocmask(SIG_BLOCK, &blocked_mask, &old_mask) == -1) {
        perror("sigprocmask SIG_BLOCK failed");
        return EXIT_FAILURE;
    }

    // 3. Critical section (where SIGINT is blocked)
    for (int i = 0; i < 5; i++) {
        printf("Waiting... (%d seconds left)\n", 5 - i);
        sleep(1);
    }

    // 4. Restore the original signal mask (unblock SIGINT)
    if (sigprocmask(SIG_SETMASK, &old_mask, NULL) == -1) {
        perror("sigprocmask SIG_SETMASK failed");
        return EXIT_FAILURE;
    }

    printf("SIGINT unblocked. Program exiting normally.\n");
    // If SIGINT was pending during the loop, it will be delivered here.

    return EXIT_SUCCESS;
}
